@patch
def hist_input(self:BFrame, n:int):
    lo,hi = Array([minimum.reduce_first, maximum.reduce_first])(self)
    w = (hi-lo)/n
    starts = lo+w*iota(n)
    return BFrame(dict(x=starts+w/2,
        count=take(n, where.undo(interval_index(starts[1:], self)))))

